            yield return option;

        yield return new NarrativeOption("valeman_youth_pack_mules_option", new TextObject("{=bab_valeman_youth_pack_mules_title}led pack mules along the high road."), new TextObject("{=bab_valeman_youth_pack_mules_desc}You learned every steep turn, shrine, inn, and shelter between the Gates of the Moon and the mountain valleys while coaxing laden mules over dangerous ground."), (args, u) => u.UpgradeScoutingRidingSkills(args, DefaultCharacterAttributes.Endurance), ccm => IsValeman(ccm) && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.MerchantUrban || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Farmer || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Hunter), ccm => SelectYouth(ccm, "merchant", "act_childhood_fox"));

        yield return new NarrativeOption("valeman_youth_squire_option", new TextObject("{=bab_valeman_youth_squire_title}served a knight as page and squire."), new TextObject("{=bab_valeman_youth_squire_desc}Through your family's service you entered the courts of the Eyrie and its bannermen, carrying messages, tending horses and harness, and training beneath an experienced knight."), (args, u) => u.UpgradeRidingPolearmSkills(args, DefaultCharacterAttributes.Endurance), ccm => IsValeman(ccm) && (!CharacterObject.PlayerCharacter.IsFemale && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Retainer || NarrativeChoiceState.ChildhoodWas("childhood_horse_option", "valeman_childhood_mountain_climber_option") || NarrativeChoiceState.EducationWas("valeman_education_mountain_page_option"))), ccm => SelectYouth(ccm, "noble", "act_childhood_apprentice"));
        yield return new NarrativeOption("valeman_youth_levy_option", new TextObject("{=bab_valeman_youth_levy_title}trained with the local levy."), new TextObject("{=bab_valeman_youth_levy_desc}You drilled with the spears, shields, and bows used by the smallfolk of the Vale, learning to hold formation when fear and noise broke less disciplined ranks."), (args, u) => u.UpgradePolearmOneHandedSkills(args, DefaultCharacterAttributes.Vigor), ccm => IsValeman(ccm) && (!CharacterObject.PlayerCharacter.IsFemale && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Farmer || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.ArtisanUrban || NarrativeChoiceState.ChildhoodWas("childhood_brawn_option"))), ccm => SelectYouth(ccm, "infantry", "act_childhood_fierce"));
        yield return new NarrativeOption("valeman_youth_scout_option", new TextObject("{=bab_valeman_youth_scout_title}ranged ahead of travellers and hunting parties."), new TextObject("{=bab_valeman_youth_scout_desc}Your knowledge of high roads and mountain passes made you useful as a guide and scout, watching for broken tracks, hostile riders, and safe ground ahead."), (args, u) => u.UpgradeScoutingBowSkills(args, DefaultCharacterAttributes.Cunning), ccm => IsValeman(ccm) && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Hunter || NarrativeChoiceState.ChildhoodWas("childhood_detail_option", "valeman_childhood_mountain_climber_option")), ccm => SelectYouth(ccm, "skirmisher", "act_childhood_fox"));
        yield return new NarrativeOption("valeman_youth_courtier_option", new TextObject("{=bab_valeman_youth_courtier_title}learned to survive the intrigues of a noble court."), new TextObject("{=bab_valeman_youth_courtier_desc}You remained among the courts of the Eyrie and its bannermen, mastering household accounts, correspondence, courtesy, and the alliances hidden beneath feasts and ceremonies."), (args, u) => u.UpgradeStewardCharmSkills(args, DefaultCharacterAttributes.Social), ccm => IsValeman(ccm) && (CharacterObject.PlayerCharacter.IsFemale && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Retainer || NarrativeChoiceState.EducationWas("education_retainer_lady_option", "valeman_education_mountain_lady_option"))), ccm => SelectYouth(ccm, "noble", "act_childhood_manners"));
        yield return new NarrativeOption("valeman_youth_factor_option", new TextObject("{=bab_valeman_youth_factor_title}acted as a young factor for your family."), new TextObject("{=bab_valeman_youth_factor_desc}You travelled through Gulltown and the Vale's guarded roads, inspecting goods, keeping accounts, and bargaining with people who respected profit more than birth."), (args, u) => u.UpgradeTradeCharmSkills(args, DefaultCharacterAttributes.Intelligence), ccm => IsValeman(ccm) && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.MerchantUrban || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.ArtisanUrban || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Farmer), ccm => SelectYouth(ccm, "merchant", "act_childhood_book"));
