        yield return new NarrativeOption("valeman_adulthood_tourney_knight_option", new TextObject("{=bab_valeman_adulthood_tourney_knight_title}you travelled the tourney circuit as a knight."), new TextObject("{=bab_valeman_adulthood_tourney_knight_desc}With horse, armour, and hard-won skill, you rode from one tourney in Westeros to the next, testing yourself in melees and lists while seeking ransom, patronage, and renown."), (args, u) => { u.UpgradeRidingPolearmSkills(args, DefaultCharacterAttributes.Endurance); args.SetRenownToAdd(20); }, ccm => IsValeman(ccm) && (!CharacterObject.PlayerCharacter.IsFemale && NarrativeChoiceState.YouthWas("valeman_youth_squire_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_childhood_apprentice"));
        yield return new NarrativeOption("valeman_adulthood_mystery_knight_option", new TextObject("{=bab_valeman_adulthood_mystery_knight_title}you entered the lists as a mystery knight."), new TextObject("{=bab_valeman_adulthood_mystery_knight_desc}Hidden behind an unknown device and a closed helm, you defied custom and entered the lists. Whatever the heralds guessed, your courage and skill could not be dismissed."), (args, u) => { u.UpgradeRidingPolearmSkills(args, DefaultCharacterAttributes.Endurance); args.SetRenownToAdd(20); }, ccm => IsValeman(ccm) && (CharacterObject.PlayerCharacter.IsFemale && NarrativeChoiceState.YouthWas("valeman_youth_rebellious_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_childhood_fierce"));
        yield return new NarrativeOption("valeman_adulthood_campaign_option", new TextObject("{=bab_valeman_adulthood_campaign_title}you distinguished yourself during a local campaign."), new TextObject("{=bab_valeman_adulthood_campaign_desc}When banners were called in the Vale, you marched with the host and kept your courage when scouting, skirmishing, and hard close fighting replaced youthful drills."), (args, u) => { u.UpgradeLeadershipTacticsSkills(args, DefaultCharacterAttributes.Cunning); args.SetRenownToAdd(15); }, ccm => IsValeman(ccm) && (!CharacterObject.PlayerCharacter.IsFemale && NarrativeChoiceState.YouthWas("valeman_youth_levy_option", "valeman_youth_scout_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_drafted_to_war_pose"));
        yield return new NarrativeOption("valeman_adulthood_court_service_option", new TextObject("{=bab_valeman_adulthood_court_service_title}you won influence in a great household."), new TextObject("{=bab_valeman_adulthood_court_service_desc}Your judgment, discretion, and command of household politics earned you trust in the courts of the Eyrie and its bannermen, and people began seeking your help before presenting delicate requests."), (args, u) => { u.UpgradeStewardCharmSkills(args, DefaultCharacterAttributes.Social); args.SetRenownToAdd(10); }, ccm => IsValeman(ccm) && (NarrativeChoiceState.YouthWas("valeman_youth_courtier_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_childhood_manners"));
        yield return new NarrativeOption("valeman_adulthood_trade_venture_option", new TextObject("{=bab_valeman_adulthood_trade_venture_title}you completed a profitable trading venture."), new TextObject("{=bab_valeman_adulthood_trade_venture_desc}You organized credit, guards, transport, and buyers for a venture through Gulltown and the Vale's guarded roads, returning with both profit and a reputation for sound judgment."), (args, u) => { u.UpgradeTradeLeadershipSkills(args, DefaultCharacterAttributes.Intelligence); args.SetRenownToAdd(10); }, ccm => IsValeman(ccm) && (NarrativeChoiceState.YouthWas("valeman_youth_factor_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_childhood_decisive"));
